function maxGridPath(grid, K) {
  const n = grid.length, m = grid[0].length;
  const NEG = -Infinity;
  const dp = Array.from({length: n}, () => Array.from({length: m}, () => Array(K+1).fill(NEG)));
  dp[0][0][0] = grid[0][0];
  for (let i=0; i<n; i++) {
    for (let j=0; j<m; j++) {
      for (let k=0; k<=K; k++) {
        const v = grid[i][j];
        if (i>0) dp[i][j][k] = Math.max(dp[i][j][k], dp[i-1][j][k] + v);
        if (j>0) dp[i][j][k] = Math.max(dp[i][j][k], dp[i][j-1][k] + v);
        if (k>0 && v < 0) {
          if (i>0) dp[i][j][k] = Math.max(dp[i][j][k], dp[i-1][j][k-1]);
          if (j>0) dp[i][j][k] = Math.max(dp[i][j][k], dp[i][j-1][k-1]);
        }
      }
    }
  }
  return Math.max(...dp[n-1][m-1]);
}
```

